const ALDRIC = person('Ser Aldric', '🛡️', { robe: '#3f5a8a', hat: 'helm', hatColor: '#b8bcc6', beard: true, hair: '#8a8a8a' });
const WIM = person('Wim', '👦', { robe: '#a0785a', hat: 'cap', hatColor: '#6b3f2a', small: true, hair: '#b8743c' });
